import{_ as t,o as e,c as d,Q as a}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Receptionist Job Application","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/14-receptionist-job-application.md","filePath":"en/more/maltese/practice/emails/14-receptionist-job-application.md"}'),r={name:"en/more/maltese/practice/emails/14-receptionist-job-application.md"},n=a('<h1 id="receptionist-job-application" tabindex="-1">Receptionist Job Application <a class="header-anchor" href="#receptionist-job-application" aria-label="Permalink to &quot;Receptionist Job Application&quot;">​</a></h1><p><strong>Scenario:</strong> The applicant writes to a hotel (also usable for a bank) to apply for the position of receptionist.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:info@lukanda.com" target="_blank" rel="noreferrer">info@lukanda.com</a><strong>Mingħand (From):</strong> [isem]@email.com <strong>Data (Date):</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Applikazzjoni ta&#39; xogħol ta&#39; receptionist</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@lukanda.com" target="_blank" rel="noreferrer">info@lukanda.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; receptionist</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; receptionist.</p><p>Għandi esperjenza ta&#39; tliet snin fis-servizz tal-klijenti.</p><p>Naf nitkellem Malti, Ingliż u ftit Taljan.</p><p>Nista&#39; nwieġeb it-telefon u nilqa&#39; lill-klijenti b&#39;mod edukat.</p><p>Jien nadif, puntwali u responsabbli.</p><p>Nista&#39; naħdem billejl u fi tmiem il-ġimgħa.</p><p>Naf nuża l-kompjuter u nittratta mal-flus b&#39;attenzjoni.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@lukanda.com" target="_blank" rel="noreferrer">info@lukanda.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:info@lukanda.com" target="_blank" rel="noreferrer">info@lukanda.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:info@lukanda.com" target="_blank" rel="noreferrer">info@lukanda.com</a></td><td>email address</td><td>The hotel&#39;s recruitment email (example)</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>Translation:</strong> From: [your name]@email.com</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td>[isem]@email.com</td><td>email address</td><td>Placeholder for your email; replace with your real one</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 15 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>15</td><td>fifteen</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; receptionist</p><p><strong>Translation:</strong> Subject: Application for the Position of Receptionist</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Applikazzjoni</td><td>application</td><td>Feminine loanword from application</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>xogħol</td><td>work; job</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>receptionist</td><td>receptionist; front-desk clerk</td><td>Loanword from receptionist</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>Translation:</strong> Dear Sir / Madam,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form</td></tr><tr><td>Sinjur</td><td>sir; Mr.</td><td>Masculine noun</td></tr><tr><td>/</td><td>or</td><td>Indicates a choice between two</td></tr><tr><td>Sinjura</td><td>madam; Mrs.</td><td>Feminine noun</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; receptionist.</p><p><strong>Translation:</strong> I am writing to apply for the position of receptionist.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>am (progressive marker)</td><td>Used with a verb to indicate an ongoing action</td></tr><tr><td>nikteb</td><td>I write</td><td>First-person singular present</td></tr><tr><td>biex</td><td>in order to</td><td>Introduces a purpose clause</td></tr><tr><td>napplika</td><td>I apply</td><td>First-person singular form, loanword from apply</td></tr><tr><td>għall-impjieg</td><td>for the job</td><td>Contracted <code>għal</code> + <code>l-impjieg</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>receptionist</td><td>receptionist</td><td>Loanword from receptionist</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; tliet snin fis-servizz tal-klijenti.</p><p><strong>Translation:</strong> I have three years of experience in customer service.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>esperjenza</td><td>experience</td><td>Feminine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>tliet</td><td>three</td><td>Numeral followed by a plural noun</td></tr><tr><td>snin</td><td>years</td><td>Plural of <code>sena</code></td></tr><tr><td>fis-servizz</td><td>in service</td><td>Contracted <code>f&#39;</code> + <code>is-servizz</code></td></tr><tr><td>tal-klijenti</td><td>of the customers</td><td>Contracted <code>ta&#39;</code> + <code>il-klijenti</code> (plural)</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Naf nitkellem Malti, Ingliż u ftit Taljan.</p><p><strong>Translation:</strong> I can speak Maltese, English, and a little Italian.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Naf</td><td>I know; I can</td><td>First-person singular form</td></tr><tr><td>nitkellem</td><td>I speak</td><td>First-person singular form</td></tr><tr><td>Malti</td><td>Maltese</td><td>Language name</td></tr><tr><td>Ingliż</td><td>English</td><td>Language name</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>ftit</td><td>a little; a few</td><td>Quantifier</td></tr><tr><td>Taljan</td><td>Italian</td><td>Language name</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; nwieġeb it-telefon u nilqa&#39; lill-klijenti b&#39;mod edukat.</p><p><strong>Translation:</strong> I can answer the phone and greet customers politely.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular form</td></tr><tr><td>nwieġeb</td><td>I answer</td><td>First-person singular form</td></tr><tr><td>it-telefon</td><td>the telephone</td><td>Masculine noun with the definite article</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>nilqa&#39;</td><td>I receive; I welcome</td><td>First-person singular form</td></tr><tr><td>lill-klijenti</td><td>to the customers</td><td>Contracted <code>li</code> + <code>l-klijenti</code>, marks the object</td></tr><tr><td>b&#39;mod</td><td>in a ... way</td><td><code>b&#39;</code> &quot;with&quot; + <code>mod</code> &quot;manner&quot;</td></tr><tr><td>edukat</td><td>polite; well-mannered</td><td>Adjective</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Jien nadif, puntwali u responsabbli.</p><p><strong>Translation:</strong> I am tidy, punctual, and responsible.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>First-person singular pronoun</td></tr><tr><td>nadif</td><td>tidy; clean</td><td>Adjective</td></tr><tr><td>puntwali</td><td>punctual</td><td>Adjective loanword from punctual</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>responsabbli</td><td>responsible</td><td>Adjective loanword from responsible</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naħdem billejl u fi tmiem il-ġimgħa.</p><p><strong>Translation:</strong> I can work at night and at weekends.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular form</td></tr><tr><td>naħdem</td><td>I work</td><td>First-person singular present</td></tr><tr><td>billejl</td><td>at night</td><td>Contracted form of <code>bil-lejl</code> &quot;in the evening/night&quot;</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>fi</td><td>in</td><td>Variant of the preposition <code>f&#39;</code></td></tr><tr><td>tmiem</td><td>end; close</td><td><code>tmiem il-ġimgħa</code> is a fixed phrase meaning &quot;weekend&quot;</td></tr><tr><td>il-ġimgħa</td><td>the week</td><td>Feminine noun with the definite article</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Naf nuża l-kompjuter u nittratta mal-flus b&#39;attenzjoni.</p><p><strong>Translation:</strong> I can use a computer and handle money carefully.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Naf</td><td>I know; I can</td><td>First-person singular form</td></tr><tr><td>nuża</td><td>I use</td><td>First-person singular form</td></tr><tr><td>l-kompjuter</td><td>the computer</td><td>Masculine noun with the definite article</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>nittratta</td><td>I handle; I treat</td><td>First-person singular form, loanword from treat</td></tr><tr><td>mal-flus</td><td>with the money</td><td>Contracted <code>ma&#39;</code> + <code>il-flus</code> (plural)</td></tr><tr><td>b&#39;attenzjoni</td><td>carefully; with attention</td><td><code>b&#39;</code> + <code>attenzjoni</code> &quot;attention&quot;</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>Translation:</strong> I hope to hear from you soon.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>nisma&#39;</td><td>I hear; receive news</td><td>First-person singular form</td></tr><tr><td>mingħandkom</td><td>from you (plural)</td><td><code>mingħand</code> + <code>-kom</code> &quot;you&quot;</td></tr><tr><td>dalwaqt</td><td>soon</td><td>Adverb</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>Translation:</strong> Thank you for considering my application.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Polite phrase</td></tr><tr><td>talli</td><td>for (your) ...</td><td>Written expression introducing a reason</td></tr><tr><td>qiesu</td><td>they considered</td><td>Third-person plural past of <code>qies</code></td></tr><tr><td>l-applikazzjoni</td><td>the application</td><td>Feminine noun with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>Translation:</strong> Regards, [your name] (formal email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Ismek</td><td>your name</td><td><code>isem</code> &quot;name&quot; + <code>-ek</code> &quot;your&quot;; replace with your real name</td></tr></tbody></table>',61),o=[n];function i(l,s,h,p,c,u){return e(),d("div",null,o)}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
